{
  "existing": [
    {
      "candidate_name": "IS_PLAN",
      "matched_existing_name": "PLANS_NEXT_ACTION"
    },
    {
      "candidate_name": "FORMULATES_HYPOTHESIS",
      "matched_existing_name": "PROPOSES_TESTABLE_HYPOTHESIS"
    },
    {
      "candidate_name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
      "matched_existing_name": "GROUNDS_CONCLUSION_IN_OBSERVATION"
    },
    {
      "candidate_name": "TESTS_ASSUMPTION_WITH_PROBE",
      "matched_existing_name": "TESTS_ASSUMPTION_WITH_PROBE"
    }
  ],
  "new": [
    {
      "name": "REVISES_HYPOTHESIS_USING_CONTRADICTING_OBSERVATION",
      "definition": "A prior expectation or hypothesis is replaced or corrected after an observation produces a result incompatible with it, with the revised reasoning explicitly incorporating that contradictory evidence.",
      "parameters": [
        {
          "name": "prior_reasoning",
          "type": "reasoning",
          "description": "The earlier reasoning that states the expectation or hypothesis being revised."
        },
        {
          "name": "contradicting_observation",
          "type": "observation",
          "description": "The observation reporting a result incompatible with the prior expectation."
        },
        {
          "name": "revised_reasoning",
          "type": "reasoning",
          "description": "The reasoning that corrects or replaces the prior expectation in light of the contradictory observation."
        }
      ],
      "assertion_conditions": [
        "The prior reasoning asserts a specific expectation or hypothesis.",
        "The observation reports a result that does not match that expectation.",
        "The revised reasoning changes the expectation and references the conflicting result as the reason."
      ],
      "exclusion_conditions": [
        "No prior expectation or hypothesis is identifiable.",
        "The observation adds information without contradicting the prior expectation.",
        "The revision is unrelated to the observation."
      ]
    }
  ],
  "uncertain": [
    {
      "name": "DETECTS_EVIDENCE_INCONSISTENCY",
      "definition": "The reasoning identifies a conflict, mismatch, or contradiction among observed facts or between an expected structure and the observed evidence, marking it as something that must be resolved.",
      "parameters": [
        {
          "name": "reasoning",
          "type": "reasoning",
          "description": "The agent text identifying an inconsistency or contradiction in the evidence."
        }
      ],
      "assertion_conditions": [
        "The reasoning explicitly points to incompatible values, shapes, behaviors, or expectations.",
        "The situation is characterized as inconsistent, contradictory, or surprising in a way that requires resolution."
      ],
      "exclusion_conditions": [
        "The reasoning reports or summarizes observations without flagging incompatibility.",
        "The reasoning only restates an error message without identifying a conflict.",
        "The reasoning immediately accepts the evidence without noting any conflict."
      ]
    },
    {
      "name": "DIAGNOSES_FAILURE_CAUSE",
      "definition": "The reasoning attributes an observed failure, error, or unexpected result to a specific cause that explains why it occurred and points toward a correction.",
      "parameters": [
        {
          "name": "reasoning",
          "type": "reasoning",
          "description": "The agent text explaining the cause of an observed failure or unexpected result."
        }
      ],
      "assertion_conditions": [
        "An observed failure, error, or mismatch is referenced.",
        "A specific cause is identified, such as an incorrect assumption, dimension, count, or configuration.",
        "The reasoning connects the identified cause to the observed failure."
      ],
      "exclusion_conditions": [
        "The reasoning merely reports the failure without explaining it.",
        "The reasoning proposes a cause unrelated to the observed result.",
        "The reasoning notes an inconsistency without attributing it to any specific cause."
      ]
    },
    {
      "name": "DECIDES_ROBUST_STRATEGY_UNDER_AMBIGUITY",
      "definition": "The reasoning acknowledges unresolved alternative interpretations or uncertainties and selects a strategy intended to remain valid across those alternatives rather than committing to a single unverified interpretation.",
      "parameters": [
        {
          "name": "reasoning",
          "type": "reasoning",
          "description": "The agent text acknowledging ambiguity and selecting a strategy that accommodates multiple interpretations."
        }
      ],
      "assertion_conditions": [
        "Multiple possible interpretations or an unresolved uncertainty are acknowledged.",
        "The selected approach is explicitly designed to accommodate or hedge against those alternatives."
      ],
      "exclusion_conditions": [
        "A single interpretation is chosen without acknowledging alternatives.",
        "The reasoning is a routine plan with no ambiguity present.",
        "The reasoning merely concludes which interpretation is correct without selecting a strategy for handling uncertainty."
      ]
    },
    {
      "name": "IMPLEMENTS_INFERRED_DESIGN",
      "definition": "An action creates or modifies an artifact that encodes a design or specification inferred from earlier evidence, rather than merely gathering information.",
      "parameters": [
        {
          "name": "design_reasoning",
          "type": "reasoning",
          "description": "The reasoning articulating the design or specification inferred from evidence."
        },
        {
          "name": "implementation_action",
          "type": "action",
          "description": "The action creating or modifying an artifact that implements the inferred design."
        }
      ],
      "assertion_conditions": [
        "The reasoning specifies a structure or behavior to be implemented and identifies it as derived from observed evidence.",
        "The action writes or modifies an artifact whose content corresponds to that specification."
      ],
      "exclusion_conditions": [
        "The action only inspects or queries existing state.",
        "The artifact content does not correspond to the inferred specification.",
        "The reasoning only states a plan without specifying the design to be implemented."
      ]
    }
  ]
}

